function W([string]$p,[string]$t){$full=Join-Path $root $p;$dir=Split-Path $full -Parent;if(!(Test-Path $dir)){New-Item -ItemType Directory -Path $dir -Force|Out-Null};[IO.File]::WriteAllText($full,$t,[Text.UTF8Encoding]::new($false))}
function Branch([string]$b){git switch -c $b | Out-Host}
