function Regression([bool]$angular=$false){dotnet build CRM.sln -c Release;if($LASTEXITCODE){throw 'build failed'};dotnet test tests\CRM.UnitTests\CRM.UnitTests.csproj -c Release --no-build;if($LASTEXITCODE){throw 'unit failed'};dotnet test tests\CRM.ArchitectureTests\CRM.ArchitectureTests.csproj -c Release --no-build;if($LASTEXITCODE){throw 'arch failed'};if($angular){Push-Location frontend\crm-web;npm test;if($LASTEXITCODE){throw 'angular test failed'};npm run build;if($LASTEXITCODE){throw 'angular build failed'};Pop-Location}}
function StopPorts([int[]]$ports){foreach($port in $ports){$ls=Get-NetTCPConnection -State Listen -LocalPort $port -ErrorAction SilentlyContinue;foreach($l in $ls){$p=Get-Process -Id $l.OwningProcess -ErrorAction SilentlyContinue;$ci=Get-CimInstance Win32_Process -Filter "ProcessId=$($l.OwningProcess)" -ErrorAction SilentlyContinue;if(($p.Path -like '*CRM_S20_ISOLATED*CRM.Api*') -or ($ci.CommandLine -like '*CRM_S20_ISOLATED*')){Stop-Process -Id $l.OwningProcess -Force -ErrorAction SilentlyContinue}}}}
function WaitUrl([string]$u){for($i=0;$i-lt80;$i++){try{$x=Invoke-WebRequest -UseBasicParsing $u -TimeoutSec 2;if($x.StatusCode-eq200){return}}catch{};Start-Sleep -Milliseconds 500};throw "timeout $u"}
